/// <summary>
/// The METSalesOrderLoadPlanningController class is the helper class for the associated SRS Report.
/// </summary>
class METSalesOrderLoadPlanningController extends SrsReportRunController
{
}

Method.Source:
public static METSalesOrderLoadPlanningController construct()
{
    return new METSalesOrderLoadPlanningController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METSalesOrderLoadPlanningController controller = METSalesOrderLoadPlanningController::construct();
    controller.parmReportName(ssrsReportStr(METSalesLoadPlanningReport, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    METSalesOrderLoadPlanningContract salesLoadPlanningContract = controller.parmReportContract().parmRdpContract() as METSalesOrderLoadPlanningContract;
    METOrderExtractScreenParameters metOrderExtractScreenParameters = _args.parmObject();

    if (metOrderExtractScreenParameters && salesLoadPlanningContract)
    {
        str selectedExtratedOrders = _args.parm();

        if (strLen(selectedExtratedOrders) > 0)
        {
            salesLoadPlanningContract.parmSelectedRecords(selectedExtratedOrders);
        }

        salesLoadPlanningContract.parmWareHouseId(metOrderExtractScreenParameters.parmWarehouse());
        salesLoadPlanningContract.parmInventSiteId(metOrderExtractScreenParameters.parmSite());
        salesLoadPlanningContract.parmConfirmedShipDateFrom(metOrderExtractScreenParameters.parmShippingDateConfirmFrom());
        salesLoadPlanningContract.parmConfirmedShipDateTo(metOrderExtractScreenParameters.parmShippingDateConfirmTo());                
    }

    controller.startOperation();
}

/// <summary>
/// Loads from saved last value.
/// </summary>
protected void loadFromSysLastValue()
{
    //Do not load ranges and filters because they are always created from scratch.
    return;
}
